mapper.select:
        select
        comment.*,
        teacher.name,
        teacher.head_img,
        users.nick_name,
        users.avatar
        from comment comment
        left join teacher teacher on comment.teacher_id = teacher.id
		left join users users on comment.user_id = users.id

            and comment.id = #{id}
            and comment.content = #{content}
            and comment.order_id = #{orderId}
            and comment.user_id = #{userId}
            and comment.teacher_id = #{teacherId}
            and comment.parent_id = #{parentId}
            and users.nick_name like concat('%',#{nickName},'%') or teacher.name like concat('%',#{nickName},'%')
            and comment.order_id in (${orderIds})


            limit #{current},#{pageSize}

